<?php require_once __DIR__.'/includes/fitur.php';if (strtolower(trim($_SESSION['role'] ?? '')) === 'admin') { header('Location: dashboard.php'); exit; } $uid=(int)$_SESSION['user_id'];$q=$pdo->prepare('SELECT nama,username,role,foto_profil FROM users WHERE id=?');$q->execute([$uid]);$u=$q->fetch();$total=(int)$pdo->query('SELECT COUNT(*) FROM servis')->fetchColumn();$active=(int)$pdo->query("SELECT COUNT(*) FROM servis WHERE status != 'Selesai'")->fetchColumn();$done=(int)$pdo->query("SELECT COUNT(*) FROM servis WHERE status = 'Selesai'")->fetchColumn();pagehead('Dashboard User');?>
<section class="card"><h2>Halo, <?=esc($u['nama'])?>!</h2><?php if($u['foto_profil']):?><img class="avatar" src="<?=esc($u['foto_profil'])?>" alt="Foto profil"><?php endif;?><p class="muted">Akun <?=esc($u['username'])?> · <?=esc($u['role'])?></p><a class="btn" href="pengaturan_user.php">Edit Profil</a></section><div class="grid"><section class="card"><div class="muted">Total Servis</div><div class="stat"><?=$total?></div></section><section class="card"><div class="muted">Dalam Proses</div><div class="stat"><?=$active?></div></section><section class="card"><div class="muted">Selesai</div><div class="stat"><?=$done?></div></section></div><?php pagefoot();
